// Renders the PWA icon set in public/ from assets/icon.png.
//
// The native builds get their icons generated by Expo at build time from
// app.json; the web build does not — a browser only sees what the manifest and
// the <link rel="apple-touch-icon"> point at, so those files have to exist as
// real files in public/. They are committed, and this script is how you redo
// them after changing assets/icon.png. Nothing in the build depends on it.
//
// Two shapes come out of it:
//   - "any": the source square, untouched. What Safari puts on the home screen
//     (iOS applies its own squircle mask) and what a desktop browser shows.
//   - "maskable": the same art inset to 85%, because Android may crop a
//     maskable icon to a circle and only the middle 80% is guaranteed to
//     survive. The inset background is the source's own corner colour, so the
//     padding is invisible.
//
// Usage: node scripts/gen-pwa-icons.mjs

import { mkdirSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// jimp-compact arrives with @expo/image-utils, which every Expo project has.
// Resolved defensively rather than imported at the top so a hoisting change
// produces this sentence instead of a stack trace.
let Jimp;
try {
  Jimp = (await import('jimp-compact')).default;
} catch {
  console.error('jimp-compact could not be resolved. Install it with: npm i -D jimp-compact');
  process.exit(1);
}

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const source = path.join(root, 'assets', 'icon.png');
const outDir = path.join(root, 'public', 'icons');

/** Fraction of the canvas the artwork occupies in a maskable icon. */
const MASKABLE_SCALE = 0.85;

const icons = [
  // 180 is the size iOS asks for on every phone still worth supporting; it is
  // the only one Safari reads for the home screen.
  { file: path.join(root, 'public', 'apple-touch-icon.png'), size: 180, maskable: false },
  { file: path.join(outDir, 'icon-192.png'), size: 192, maskable: false },
  { file: path.join(outDir, 'icon-512.png'), size: 512, maskable: false },
  { file: path.join(outDir, 'icon-maskable-192.png'), size: 192, maskable: true },
  { file: path.join(outDir, 'icon-maskable-512.png'), size: 512, maskable: true },
];

mkdirSync(outDir, { recursive: true });

const original = await Jimp.read(source);
// The corner rather than a hard-coded hex: whatever icon.png is replaced with,
// its own background keeps filling the maskable padding.
const background = original.getPixelColor(0, 0);

for (const { file, size, maskable } of icons) {
  let image;

  if (maskable) {
    const inner = Math.round(size * MASKABLE_SCALE);
    const offset = Math.round((size - inner) / 2);
    image = new Jimp(size, size, background);
    image.composite(original.clone().resize(inner, inner, Jimp.RESIZE_BICUBIC), offset, offset);
  } else {
    image = original.clone().resize(size, size, Jimp.RESIZE_BICUBIC);
  }

  await image.writeAsync(file);
  console.log(`${path.relative(root, file)}  ${size}x${size}${maskable ? '  (maskable)' : ''}`);
}
